PrologProcedure:
#Region CallThisProcess
# A snippet of code provided as an example how to call this process should the developer be working on a system without access to an editor with auto-complete.
IF( 1 = 0 );
    ExecuteProcess( '}bedrock.hier.element.create', 'pLogOutput', pLogOutput,
      'pStrictErrorHandling', pStrictErrorHandling,
      'pDim', '', 'pHier', '', 'pEle', '',
      'pEleType', '', 'pInsertionPoint', '',
      'pDelim', '&'
  );
ENDIF;
#EndRegion CallThisProcess
 
#****Begin: Generated Statements***
#****End: Generated Statements****
 
################################################################################################### 
##~~Join the bedrock TM1 community on GitHub https://github.com/cubewise-code/bedrock-5 Ver 5.0~~## 
################################################################################################### 
 
#Region @DOC
# Description:
# This process will create new element in a dimension Hierarchy. More elements than one will be
# created if pEle is supplied with a delimited list of elements.
 
# Note:
# Valid dimension name (pDim) and element list are mandatory, otherwise the process will abort.
 
# Caution: When target hierarchy is `Leaves`, no consolidated elements will be created.
#EndRegion @DOC
 
### Global Variables
pJson = IF( pJson @= '', '{}', pJson );
StringGlobalVariable(  'sBedrockReturnValue' );
NumericGlobalVariable( 'nBedrockReturnValue' );
 
### Constants ###
cThisProcName     = GetProcessName();
cTimeStamp        = TimSt( Now, '\Y\m\d\h\i\s' );
cRandomInt        = NumberToString( INT( RAND( ) * 100000 ));
cTemp             = cThisProcName |'_'| cTimeStamp |'_'| cRandomInt;
cTempDataSource   = cTemp | '_datasource';
cUserName         = TM1User();
cMsgErrorLevel    = 'ERROR';
cMsgErrorContent  = 'User:%cUserName% Process:%cThisProcName% ErrorMsg:%sMessage%';
cMsgInfoContent   = 'User:%cUserName% Process:%cThisProcName% Message:%sMessage%';
cLogInfo          = 'Process:%cThisProcName% run with parameters pDim:%pDim%, pHier:%pHier%, pEle:%pEle%, pEleType:%pEleType%, pInsertionPoint:%pInsertionPoint%, pDelim:%pDelim%.';

#################################################################################################
#Region - Process Parameters

pJson = IF( JsonType( pJson ) @<> 'object', '{}', pJson );
sMessages = '{"Process": "'|GetProcessName()|'", "User": "'|TM1User()|'", "Info": ["Process: '''|GetProcessName()|''' run by User: '''|TM1User()|'''."], "Error": []}';
pDefaultParameters = '{
  "pDelim":               "&",
  "pDim":                 null,
  "pEle":                 null,
  "pEleType":             "N",
  "pHier":                "",
  "pInsertionPoint":      "",
  "pCtrlObj":             0,
  "pLogOutput":           0,
  "pStrictErrorHandling": 0
}';

pPassedParameters = '{
  "pDelim":               '|StringToJson  ( pDelim               )|',
  "pDim":                 '|StringToJson  ( pDim                 )|',
  "pEle":                 '|StringToJson  ( pEle                 )|',
  "pEleType":             '|StringToJson  ( pEleType             )|',
  "pHier":                '|StringToJson  ( pHier                )|',
  "pInsertionPoint":      '|StringToJson  ( pInsertionPoint      )|',
  "pCtrlObj":             '|NumberToString( pCtrlObj             )|',
  "pLogOutput":           '|NumberToString( pLogOutput           )|',
  "pStrictErrorHandling": '|NumberToString( pStrictErrorHandling )|'
}';

pJson = JsonMergePatch( pPassedParameters, pJson );
# String Parameters
pDelim               =                 JsonToString( JsonGet( pJson, 'pDelim'               ) );
pDim                 =                 JsonToString( JsonGet( pJson, 'pDim'                 ) );
pEle                 =                 JsonToString( JsonGet( pJson, 'pEle'                 ) );
pEleType             =                 JsonToString( JsonGet( pJson, 'pEleType'             ) );
pHier                =                 JsonToString( JsonGet( pJson, 'pHier'                ) );
pInsertionPoint      =                 JsonToString( JsonGet( pJson, 'pInsertionPoint'      ) );
# Numeric Parameters
pCtrlObj             = StringToNumber( JsonToString( JsonGet( pJson, 'pCtrlObj'             ) ) );
pLogOutput           = StringToNumber( JsonToString( JsonGet( pJson, 'pLogOutput'           ) ) );
pStrictErrorHandling = StringToNumber( JsonToString( JsonGet( pJson, 'pStrictErrorHandling' ) ) );

### Get the parameters that differ from the default
pDiffer = JsonDiff( pDefaultParameters, pJson );
nSize = JsonSize( pDiffer );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  pDiffer = JsonReplace( pDiffer, '/'|NumberToString( nSize )|'/op', '"add"' );
END;
pJson = JsonPatch( '{}', pDiffer );

### LogOutput parameters
sMessages = JsonAdd( sMessages, '/Info/-', pJson );
IF( pLogOutput = 1 );
  LogOutput('INFO', JsonToString( sMessages, '/Info/0', 0, ' ' ) );
ENDIF;

#EndRegion - Process Parameters
#################################################################################################

## LogOutput parameters
IF( pLogoutput = 1 );
    LogOutput('INFO', Expand( cLogInfo ) );   
ENDIF;
 
################################################################################################# 
#Region - Validate Parameters

nErrors = 0;
 
# Validate dimension
IF( Trim( pDim ) @= '' );
  nErrors = 1;
  sMessage = 'No dimension specified.';
  LogOutput( cMsgErrorLevel, Expand( cMsgErrorContent ) );
ENDIF;
 
# Validate element
IF( Trim( pEle ) @= '' );
  nErrors = 1;
  sMessage = 'No element specified.';
  LogOutput( cMsgErrorLevel, Expand( cMsgErrorContent ) );
ENDIF;
 
# Validate element type
pEleType = Upper( pEleType );
IF( pEleType @= '' );
  pEleType = 'N';
ELSEIF( pEleType @<> 'N' & pEleType @<> 'C' & pEleType @<> 'S' );
  nErrors = 1;
  sMessage = 'Invalid element type: ' | pEleType;
  LogOutput( cMsgErrorLevel, Expand( cMsgErrorContent ) );
ENDIF;
 
# If blank delimiter specified then convert to default
IF( pDelim @= '' );
  pDelim = '&';
ENDIF;

# Convert pEle, pDim, and pHier to JSON
IF( JsonSize( pEle ) = -1 );
  ExecuteProcess( '}bedrock-v12.utils.string.to_list', 'pString', pEle, 'pDelimiter', pDelim, 'pTRIM', 1 );
  pEle = sBedrockReturnValue;
ENDIF;

IF( JsonSize( pDim ) = -1 );
  ExecuteProcess( '}bedrock-v12.utils.string.to_list', 'pString', pDim, 'pDelimiter', pDelim, 'pTRIM', 1 );
  pDim = sBedrockReturnValue;
ENDIF;

IF( JsonSize( pHier ) = -1 );
  ExecuteProcess( '}bedrock-v12.utils.string.to_list', 'pString', pHier, 'pDelimiter', pDelim, 'pTRIM', 1 );
  pHier = sBedrockReturnValue;
ENDIF;

### Check for errors before continuing
IF( nErrors <> 0 );
  IF( pStrictErrorHandling = 1 ); 
    ProcessQuit; 
  ELSE;
    ProcessBreak;
  ENDIF;
ENDIF;

#EndRegion - Validate Parameters
#################################################################################################

################################################################################################# 
#Region - Create Datasource

# Get Dimensions that match pDim
cTempDimension = cTemp|'_dimension';
HierarchySubsetCreate( '}Dimensions', '}Dimensions', cTemp, 1 );
HierarchySubsetCreate( '}Dimensions', '}Dimensions', cTempDimension, 1 );
HierarchySubsetCreate( '}Dimensions', '}Dimensions', cTempDimension|'_sub', 1 );

sFilter = '[]';
nSize = JsonSize( pDim );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  sDimension = JsonToString( pDim, '/'|NumberToString( nSize ) );
  IF( SCAN( '?', sDimension ) <> 0 % SCAN( '*', sDimension ) <> 0 );
    sFilter = JsonAdd( sFilter, 0, StringToJson( '{TM1FILTERBYPATTERN(TM1SUBSETALL([}Dimensions].[}Dimensions]), "'|sDimension|'")}' ) );
  ELSE;
    sFilter = JsonAdd( sFilter, 0, StringToJson( sDimension ) );
  ENDIF;
END;

sExcept = '["{TM1FILTERBYPATTERN(TM1SUBSETALL([}Dimensions].[}Dimensions]), \"*:*\")}"]';
sExcept = IF( pCtrlObj = 1, sExcept, JsonAdd( sExcept, 0, '"{TM1FILTERBYPATTERN(TM1SUBSETALL([}Dimensions].[}Dimensions]), \"}*\")}"' ) );
  
ExecuteProcess( '}bedrock-v12.hier.sub.create',
  'pDimension', '}Dimensions',
  'pSubset', cTempDimension,
  'pFilter', sFilter,
  'pExcept', sExcept,
  'pTemp', 1 );

# Get Dimensions/Hierarchies that match pHier
sFilter = '[]';
nDimensionCount = HierarchySubsetGetSize( '}Dimensions', '}Dimensions', cTempDimension );
nSize = JsonSize( pHier );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  sHierarchy = JsonToString( pHier, '/'|NumberToString( nSize ) );
  
  i = 0;
  WHILE( i < nDimensionCount );
    i = i + 1;
    sDimension = HierarchySubsetGetElementName( '}Dimensions', '}Dimensions', cTempDimension, i );
    
    # Check if sDimension matches filter
    sFilter = JsonAdd( sFilter, 0, StringToJson( '{TM1FILTERBYPATTERN({[}Dimensions].[}Dimensions].['|sDimension|']}, "'|sHierarchy|'")}' ) );
    
    IF( SCAN( '?', sHierarchy ) <> 0 % SCAN( '*', sHierarchy ) <> 0 );
      sFilter = JsonAdd( sFilter, 0, StringToJson( '{TM1FILTERBYPATTERN(TM1SUBSETALL([}Dimensions].[}Dimensions]), "'|sDimension|':'|sHierarchy|'")}' ) );
    ELSE;
      sFilter = JsonAdd( sFilter, 0, StringToJson( sDimension|':'|sHierarchy ) );
    ENDIF;
    
  END;
END;

ExecuteProcess( '}bedrock-v12.hier.sub.create',
  'pDimension', '}Dimensions',
  'pSubset', cTemp,
  'pFilter', sFilter,
  'pTemp', 1 );

# Set Datasource
DataSourceType = 'SUBSET';
DatasourceNameForServer = '}Dimensions';
DatasourceDimensionSubset = cTemp;

#EndRegion - Create Datasource
#################################################################################################

MetadataProcedure:
#****Begin: Generated Statements***
#****End: Generated Statements****

# Get sDim and sHier from vDimension
nColonIndex = SCAN( ':', vDimension );
IF( nColonIndex <> 0 );
  sDim = SUBST( vDimension, 1, nColonIndex-1 );
  sHier = DELET( vDimension, 1, nColonIndex );
ELSE;
  sDim = vDimension;
  sHier = vDimension;
ENDIF;

# Loop through pEle
nCount = JsonSize( pEle );
WHILE( nCount > 0 );
  nCount = nCount - 1;
  sEle = JsonToString( JsonGet( pEle, nCount ) );
  
  # Validate Insertion Point
  sInsertionPoint = pInsertionPoint;
  IF( pInsertionPoint @<> '' & ElementIndex( sDim, sHier, pInsertionPoint ) = 0 );
    sMessages = JsonAdd( sMessages, '/Info/-',  StringToJson( 'In Dimension: '''|sDim|''', Hierarchy: '''|sHier|''', Element Insertion Point: '''|pInsertionPoint|''' does not exist. Using '' '' as insertion point.' ) );
    sInsertionPoint = '';
  ENDIF;
  
  # Check if Element already exists
  IF( ElementIndex( sDim, sHier, sEle ) <> 0 );
    sMessages = JsonAdd( sMessages, '/Error/-', StringToJson( 'In Dimension: '''|sDim|''', Hierarchy: '''|sHier|''', Element: '''|sEle|''' already exist in hierarchy.' ) );
  # Check if trying to add a C Element to Leaves Hierarchy
  ELSEIF( sHier @= 'Leaves' & pEleType @= 'C' );
    sMessages = JsonAdd( sMessages, '/Info/-',  StringToJson( 'Cannot add C Element to ''Leaves'' hierarchy' ) );
  # Add element to hierarchy
  ELSE;
    HierarchyElementInsert( sDim, sHier, sInsertionPoint, sEle, pEleType );   
    sMessages = JsonAdd( sMessages, '/Info/-',  StringToJson( 'In Dimension: '''|sDim|''', Hierarchy: '''|sHier|''', Element: '''|sEle|''' with type '''|pEleType|''' created successfully.' ) ); 
  ENDIF;
END;

EpilogProcedure:
#****Begin: Generated Statements***
#****End: Generated Statements****

################################################################################################# 
##~~Join the bedrock TM1 community on GitHub https://github.com/cubewise-code/bedrock Ver 4.0~~##
################################################################################################# 

### Return code & final error message handling
IF( nErrors > 0 );
    sMessage = 'the process incurred at least 1 error. Please see above lines in this file for more details.';
    nProcessReturnCode = 0;
    LogOutput( cMsgErrorLevel, Expand( cMsgErrorContent ) );
    sProcessReturnCode = Expand( '%sProcessReturnCode% Process:%cThisProcName% completed with errors. Check tm1server.log for details.' );
    IF( pStrictErrorHandling = 1 ); 
        ProcessQuit; 
    ENDIF;
ELSE;
    sProcessAction     = Expand( 'Process:%cThisProcName% inserted element(s) %pEle% with type %pEleType% into %pDim%:%pHier%.' );
    sProcessReturnCode = Expand( '%sProcessReturnCode% %sProcessAction%' );
    nProcessReturnCode = 1;
    IF( pLogoutput = 1 );
        LogOutput('INFO', Expand( sProcessAction ) );   
    ENDIF;
ENDIF;


### End Epilog ###
